  SELECT count(*) INTO n FROM jsonb_populate_recordset(NULL::public."landing_products",originals->'landing_products') s WHERE NOT EXISTS (SELECT 1 FROM public."landing_products" p WHERE p."key"=s."key" AND to_jsonb(p)=to_jsonb(s));
  IF n <> 0 THEN RAISE EXCEPTION 'Existing-record preservation failed: landing_products; all inserts roll back.'; END IF;
  -- asset_network_catalog: 37 frozen rows, parent records already inserted.
