    WHERE NOT EXISTS (SELECT 1 FROM public."asset_network_catalog" p WHERE p."id"=s."id");
  GET DIAGNOSTICS n = ROW_COUNT;
  inserted_total := inserted_total + n;
  SELECT count(*) INTO n FROM jsonb_populate_recordset(NULL::public."asset_network_catalog",source_data->'asset_network_catalog') s WHERE NOT EXISTS (SELECT 1 FROM public."asset_network_catalog" p WHERE p."id"=s."id" AND to_jsonb(p)=to_jsonb(s));
  IF n <> 0 THEN RAISE EXCEPTION 'Source verification failed: asset_network_catalog; all inserts roll back.'; END IF;
