  SELECT count(*) INTO n FROM jsonb_populate_recordset(NULL::public."plan_entitlements",originals->'plan_entitlements') s WHERE NOT EXISTS (SELECT 1 FROM public."plan_entitlements" p WHERE p."plan_id"=s."plan_id" AND p."key"=s."key" AND to_jsonb(p)=to_jsonb(s));
